        "alt": "푸른 칸막이와 작업용 책상이 늘어선 초기 모노리스 소프트 사무실",
        "caption": "창립 직후 특별 인터뷰에 실린 모노리스 소프트의 사내 풍경.",
        "sourceUrl": "https://web.archive.org/web/20010421124204/http://www.monolithsoft.co.jp/interview.html",
