            "kind": "answer",
            "speaker": "모리야(守屋)",
            "text": "팀의 2D 디자이너들이 하나의 주제로 아이디어를 내며 경쟁하는 작은 공모전 같은 것이 있습니다. 그럴 때 제가 낸 아이디어가 채택되고, 그 아트를 끝까지 제대로 그려 냈을 때 기쁩니다."
