            "kind": "answer",
            "speaker": "무토(武藤)",
            "text": "제가 맡은 디자인을 많은 사람이 봐 준다는 건 참 보람 있는 일이죠. UI에 사용한 디자인 모티프는 공식 홈페이지 디자인이나 소개 영상 같은 홍보물에 활용되는 경우가 많습니다. 그런 것을 보면 ‘디자인으로서 쓰임이 있는 걸 만들었구나’ 하고 성과를 실감합니다."
