            "kind": "answer",
            "speaker": "나이토(内藤)",
            "text": "저는 생물을 너무 좋아해서 지금도 업무와 별개로 취미로 생물을 스케치하고 있습니다. 물론 일할 때는 다른 분야도 그리지만, 솔직히 말하면 크리처만 그리고 싶을 정도입니다. (웃음) 그런 저에게 여러 아트를 그릴 기회를 주고, 게임의 세계를 통해 많은 크리처를 세상에 선보일 수 있게 해 준 것에 정말 감사하고 있습니다."
