            "text": "교토 스튜디오는 닌텐도와 함께 일할 기회가 많은데, 매번 ‘무언가를 만드는 자세’의 수준이 높다는 데 자극을 받습니다. 매일 배우면서 자신을 발전시킬 수 있는 회사라고 생각합니다."
